    { id: "B1.1", base: "B1.1", material: "alpha", turns: [start, "推荐看起来不错，我还没决定。", "先等等，我暂时去处理别的事。", confirm] },
    { id: "B1.2-delayed", base: "B1.2", material: "alpha", turns: [start, modify, "确认按刚才修改后的方案编排。"] },
    { id: "B1.2-combined", base: "B1.2", material: "alpha", turns: [start, "把 {label} 的读者改成首次参加活动的访客，任务改为判断何时可以领取；其他理解问题保持。我确认按此编排。"] },
